oegen:node_1 a holon:ClinicalQuestionHolon ;
    holon:hasBoundaryGraph oeq:q_asthma_efficacy_boundary ;
    holon:hasContextGraph oeq:q_asthma_efficacy_context ;
    holon:hasInteriorGraph oeq:q_asthma_efficacy_interior ;
    holon:hasProjectionGraph oeq:q_asthma_efficacy_projection ;
    oe:answerText "Salbutamol is effective for treating asthma."^^xsd:string ;
    oe:questionText "What is the efficacy of salbutamol for treating asthma?"^^xsd:string ;
    oe:belongsToSpecialty "Cardiology" .

oegen:node_1 <https://example.org/openevidence/drugs/salbutamol> oe:treats <https://example.org/openevidence/diseases/asthma> .
